/**
 * ==============================================================================
 * DATOS Y PARTITURAS MUSICALES - SINFONÍA DE CAMPANAS (Guitar Hero Edition)
 * ==============================================================================
 * 
 * Contiene las 6 canciones oficiales de la Feria Mágica del Juguete:
 * - Canciones de Alexander Nakarada (CreatorChords) con créditos completos de autor.
 * - Soporte nativo para Notas Normales, NOTAS SOSTENIDAS (Sustain Notes) y ACORDES/NOTAS DOBLES.
 * - Star Notes oficiales con Logo de la Feria Mágica y Campuslands (Modo Estrella x4).
 * - 4 Dificultades calibradas al milisegundo: Fácil, Normal, Difícil y Experto (Guitar Hero Shredding).
 * - TODAS las dificultades utilizan activamente los 4 carriles (0, 1, 2, 3).
 */

export interface ChartNoteRecord {
  lane: number;
  time: number;
  duration?: number;
  type?: "normal" | "sustain";
  isStar?: boolean;
  logoType?: 1 | 2; // 1 = Feria Mágica, 2 = Campuslands
}

export interface SongDef {
  id: string;
  title: string;
  artist: string;
  credits: string;
  subtitle: string;
  bpm: number;
  speed: number;
  durationSeconds: number;
  stars: number;
  difficultyLabel: string;
  tagColor: string;
  audioFile: string;
  icon: "guitar" | "zap" | "flame" | "sparkles" | "crown" | "music";
}

